class MaxStack {
    list<int> dll;  // back() = top of stack
    map<int, vector<list<int>::iterator>> idx;

public:
    MaxStack() {}

    void push(int x) {
        dll.push_back(x);
        auto it = dll.end();
        --it;
        idx[x].push_back(it);
    }

    int pop() {
        int x = dll.back();
        dll.pop_back();
        idx[x].pop_back();
        if (idx[x].empty()) idx.erase(x);
        return x;
    }

    int top() {
        return dll.back();
    }

    int peekMax() {
        return idx.rbegin()->first;
    }

    int popMax() {
        int x = peekMax();
        auto it = idx[x].back();
        idx[x].pop_back();
        if (idx[x].empty()) idx.erase(x);
        dll.erase(it);
        return x;
    }
};

