class MaxStack {
    static class Node {
        int val;
        Node prev, next;
        Node(int v) { val = v; }
    }

    private final Node head, tail;
    private final TreeMap<Integer, Deque<Node>> idx;

    public MaxStack() {
        head = new Node(0);
        tail = new Node(0);
        head.next = tail;
        tail.prev = head;
        idx = new TreeMap<>();
    }

    private void append(Node n) {
        n.prev = tail.prev;
        n.next = tail;
        tail.prev.next = n;
        tail.prev = n;
    }

    private void unlink(Node n) {
        n.prev.next = n.next;
        n.next.prev = n.prev;
    }

    public void push(int x) {
        Node n = new Node(x);
        append(n);
        idx.computeIfAbsent(x, k -> new ArrayDeque<>()).addLast(n);
    }

    public int pop() {
        Node n = tail.prev;
        unlink(n);
        Deque<Node> dq = idx.get(n.val);
        dq.removeLast();
        if (dq.isEmpty()) idx.remove(n.val);
        return n.val;
    }

    public int top() {
        return tail.prev.val;
    }

    public int peekMax() {
        return idx.lastKey();
    }

    public int popMax() {
        int x = idx.lastKey();
        Deque<Node> dq = idx.get(x);
        Node n = dq.removeLast();
        if (dq.isEmpty()) idx.remove(x);
        unlink(n);
        return x;
    }
}

