import heapq
from typing import Dict, List, Optional


class Node:
    def __init__(self, val: int) -> None:
        self.val = val
        self.prev: Optional["Node"] = None
        self.next: Optional["Node"] = None


class MaxStack:
    def __init__(self) -> None:
        self.head = Node(0)
        self.tail = Node(0)
        self.head.next = self.tail
        self.tail.prev = self.head
        self.idx: Dict[int, List[Node]] = {}
        self.heap: List[int] = []  # max-heap of (-value)

    def _append(self, node: Node) -> None:
        node.prev = self.tail.prev
        node.next = self.tail
        self.tail.prev.next = node
        self.tail.prev = node

    def _unlink(self, node: Node) -> None:
        node.prev.next = node.next
        node.next.prev = node.prev

    def _drop(self, x: int) -> None:
        bucket = self.idx[x]
        bucket.pop()
        if not bucket:
            del self.idx[x]

    def _clean(self) -> None:
        while self.heap and -self.heap[0] not in self.idx:
            heapq.heappop(self.heap)

    def push(self, x: int) -> None:
        node = Node(x)
        self._append(node)
        self.idx.setdefault(x, []).append(node)
        heapq.heappush(self.heap, -x)

    def pop(self) -> int:
        node = self.tail.prev
        self._unlink(node)
        self._drop(node.val)
        return node.val

    def top(self) -> int:
        return self.tail.prev.val

    def peekMax(self) -> int:
        self._clean()
        return -self.heap[0]

    def popMax(self) -> int:
        x = self.peekMax()
        node = self.idx[x][-1]
        self._unlink(node)
        self._drop(x)
        return x

