class LFUCache {
    struct Node {
        int key, val, freq;
        Node(int k, int v, int f) : key(k), val(v), freq(f) {}
    };

    int cap, minf;
    unordered_map<int, list<Node>::iterator> where;
    unordered_map<int, list<Node>> buckets;

    void touch(list<Node>::iterator it) {
        int f = it->freq;
        Node node = *it;
        buckets[f].erase(it);
        if (buckets[f].empty()) {
            buckets.erase(f);
            if (minf == f) minf++;
        }
        node.freq++;
        buckets[node.freq].push_front(node);
        where[node.key] = buckets[node.freq].begin();
    }

public:
    LFUCache(int capacity) : cap(capacity), minf(0) {}

    int get(int key) {
        if (!where.count(key)) return -1;
        auto it = where[key];
        int val = it->val;
        touch(it);
        return val;
    }

    void put(int key, int value) {
        if (cap == 0) return;
        if (where.count(key)) {
            auto it = where[key];
            it->val = value;
            touch(it);
            return;
        }
        if ((int)where.size() == cap) {
            Node victim = buckets[minf].back();
            where.erase(victim.key);
            buckets[minf].pop_back();
            if (buckets[minf].empty()) buckets.erase(minf);
        }
        minf = 1;
        buckets[1].push_front(Node(key, value, 1));
        where[key] = buckets[1].begin();
    }
};

