class LFUCache {
    static class Node {
        int key, val, freq;
        Node prev, next;
        Node(int k, int v) {
            key = k;
            val = v;
            freq = 1;
        }
    }

    static class DLList {
        Node head, tail;
        int size;
        DLList() {
            head = new Node(0, 0);
            tail = new Node(0, 0);
            head.next = tail;
            tail.prev = head;
        }
        void addFirst(Node n) {
            n.next = head.next;
            n.prev = head;
            head.next.prev = n;
            head.next = n;
            size++;
        }
        void remove(Node n) {
            n.prev.next = n.next;
            n.next.prev = n.prev;
            size--;
        }
        Node removeLast() {
            Node n = tail.prev;
            remove(n);
            return n;
        }
    }

    private final int cap;
    private int minf;
    private final Map<Integer, Node> where;
    private final Map<Integer, DLList> buckets;

    public LFUCache(int capacity) {
        cap = capacity;
        minf = 0;
        where = new HashMap<>();
        buckets = new HashMap<>();
    }

    private void touch(Node n) {
        DLList old = buckets.get(n.freq);
        old.remove(n);
        if (old.size == 0) {
            buckets.remove(n.freq);
            if (minf == n.freq) minf++;
        }
        n.freq++;
        buckets.computeIfAbsent(n.freq, k -> new DLList()).addFirst(n);
    }

    public int get(int key) {
        Node n = where.get(key);
        if (n == null) return -1;
        touch(n);
        return n.val;
    }

    public void put(int key, int value) {
        if (cap == 0) return;
        Node n = where.get(key);
        if (n != null) {
            n.val = value;
            touch(n);
            return;
        }
        if (where.size() == cap) {
            DLList list = buckets.get(minf);
            Node victim = list.removeLast();
            where.remove(victim.key);
            if (list.size == 0) buckets.remove(minf);
        }
        Node fresh = new Node(key, value);
        where.put(key, fresh);
        buckets.computeIfAbsent(1, k -> new DLList()).addFirst(fresh);
        minf = 1;
    }
}

