from typing import Dict, Optional


class Node:
    def __init__(self, key: int = 0, val: int = 0, freq: int = 1) -> None:
        self.key = key
        self.val = val
        self.freq = freq
        self.prev: Optional["Node"] = None
        self.next: Optional["Node"] = None


class DLList:
    def __init__(self) -> None:
        self.head = Node()
        self.tail = Node()
        self.head.next = self.tail
        self.tail.prev = self.head
        self.size = 0

    def add_first(self, node: Node) -> None:
        node.next = self.head.next
        node.prev = self.head
        self.head.next.prev = node
        self.head.next = node
        self.size += 1

    def remove(self, node: Node) -> None:
        node.prev.next = node.next
        node.next.prev = node.prev
        self.size -= 1

    def remove_last(self) -> Node:
        node = self.tail.prev
        self.remove(node)
        return node


class LFUCache:
    def __init__(self, capacity: int) -> None:
        self.cap = capacity
        self.minf = 0
        self.where: Dict[int, Node] = {}
        self.buckets: Dict[int, DLList] = {}

    def _touch(self, node: Node) -> None:
        old = self.buckets[node.freq]
        old.remove(node)
        if old.size == 0:
            del self.buckets[node.freq]
            if self.minf == node.freq:
                self.minf += 1
        node.freq += 1
        self.buckets.setdefault(node.freq, DLList()).add_first(node)

    def get(self, key: int) -> int:
        node = self.where.get(key)
        if node is None:
            return -1
        self._touch(node)
        return node.val

    def put(self, key: int, value: int) -> None:
        if self.cap == 0:
            return
        node = self.where.get(key)
        if node is not None:
            node.val = value
            self._touch(node)
            return
        if len(self.where) == self.cap:
            victim = self.buckets[self.minf].remove_last()
            del self.where[victim.key]
            if self.buckets[self.minf].size == 0:
                del self.buckets[self.minf]
        fresh = Node(key, value, 1)
        self.where[key] = fresh
        self.buckets.setdefault(1, DLList()).add_first(fresh)
        self.minf = 1

