    def timeRequiredToBuy(self, tickets: List[int], k: int) -> int:
        q: Deque[int] = deque(range(len(tickets)))
        time = 0
        while q:
            i = q.popleft()
            tickets[i] -= 1
            time += 1
            if tickets[i] > 0:
                q.append(i)
            elif i == k:
                return time
        return time

